    let subtotal = 0;
    for (const sale of regionSales) {
      const amount = grossAmount(sale, taxRate);
      out.push(saleLine(sale, amount, code));
      if (amount >= LARGE_ORDER) large++;
      subtotal += amount;
      rows++;
    }
    out.push('Subtotal ' + code + ': ' + formatMoney(subtotal, code));
    out.push('');
  }

  if (rows === 0) {
    out.push('No sales.');
  } else {
    out.push('Rows: ' + rows);
    out.push('Large orders: ' + large);
  }
  return out.join('\n') + '\n';
}

